data abssas.filings;
set abssas.filings;
accession1=trim(substr(filename,length(filename)-23));
run;

data abssas.filings;
set abssas.filings;
accession=substr(accession1,1,length(accession1)-4);
run;

*read the daily CSV files into SAS;
proc sql;
select member into :name separated by '*' from abssas.name_filter;
%let count2 = &sqlobs;
quit;

*run macro below that reads in daily EDGAR files and creates variables;
%macro yy;
%local inLibref;
%do i = 1 %to &count2;
%let j = %scan(&name,&i,*);
%let inLibref=abssas;
proc import out = &inLibref..&j datafile="[redacted-path-c74ddda913d7]"
dbms=csv replace;
getnames = yes;
run; 
%end;
%mend;
%yy()

		proc sql;
		create table &inDestLib..&inMember. as select a.*,b.formtype, b.date as filing_date
		from &inLibref..&inMember. as a left join abssas.filings as b
		on a.cik=b.cik and a.accession=b.accession;
		quit;
/*keep only forms that contain "ABS" or "424", which are the formtypes associated with ABS prospectuses and ABS-EE filings, respectively*/
		data &inDestLib..&inMember.; 
            set &inDestLib..&inMember.;
			where formtype =:'ABS' or formtype =:'424' ;
		run;
/*format variables and convert time variable to a datetime variable*/
		data &inDestLib..&inMember.;
		set &inDestLib..&inMember.;
			format ip $20. accession $24.;
			hour=hour(time);
			minute=minute(time);		
			datetime=dhms(date,0,0,time);
			format datetime datetime16.;
		run;

*merge the resulting daily 424/ABS datasets in to a single data set. Because we are only
	interested in post-Reg AB II deals (i.e., those that would have an associated ABS-EE filing), 
	we only utilize daily EDGAR files after Nov 15, 2016;
data str.all_abs;
set 
str.log20161116

str.log20170628
str.log20170629
str.log20170630;
run;

create table str.abs_cik as select a.*,b.date as p1filedate 
from str.abs_cik as a left join abssas.filings as b
on a.cik=b.cik and a.pros1_acc=b.accession;
quit;

proc sql;
create table str.abs_cik as select a.*,b.date as p2filedate 
from str.abs_cik as a left join abssas.filings as b
on a.cik=b.cik and a.pros2_acc=b.accession;
quit;

proc sql;
create table str.abs_cik as select a.*,b.date as absfiledate 
from str.abs_cik as a left join abssas.filings as b
on a.cik=b.cik and a.abs_acc=b.accession;

*create 14-day filing window variables for the 1st/2nd prospectuses and ABS-EE filings;
data str.abs_cik60;
set str.abs_cik;
	p1window=p1filedate+60;
	p2window=p2filedate+60;
	abswindow=absfiledate+60;
	format p2window mmddyy10.;
	format p1window mmddyy10.;
	format abswindow mmddyy10.;
run;

*eliminate auto deals in our sample that - (1) don't have an ABS-E, (2) originated prior to
	Reg AB II (since no auto deals in our sample were subject to Reg AB II after the Nov 2016
	effective date, we eliminate any deals with an ABS-EE file date before 2017, and (3) have
	an ABS-EE file date after June, since the EDGAR download data is only availalbe through 
	June 2017; 
data str.absee_cik60;
set str.abs_cik60;
where abs_acc ne "" and year(absfiledate)=2017 and month(absfiledate)<7 and auto_ind=1;
run;

*Eliminate instances of simultaneous downloads by same user;
proc sort data=str.All_abs2017 out=str.All_abs2017_apr11 nodupkey; by ip cik accession formtype datetime; run;

proc sql;
create table str.All_abs2017 as select a.*, b.*
from str.absee_cik60 as a left join str.All_abs as b
on a.cik=b.cik
where b.cik ne .;
quit;

data str.All_abs2017_win;
set str.All_abs2017;
p1=0;
	if pros1_acc=accession and p1filedate<=date<p2filedate then p1=1;
abs=0;
	if abs_acc=accession and absfiledate<=date<p2filedate then abs=1;
where cik ne 1694276 and cik ne 1692310 and cik ne 1679731;
run;

*eliminate downloads other than the 1st prospectus or ABS-EE;
data str.All_abs2017_win;
set str.All_abs2017_win;
if p1+abs<1 then delete;
run;

* Export data sets to STATA for further analysis, including removing non-unique user downloads (see Stata .do code file named 'Data preparation and analysis code');
PROC EXPORT DATA= str.All_abs2017
            OUTFILE= "[redacted-path-1c06966df207]" 
            DBMS=STATA REPLACE;
RUN;
